window.REPORT_PRELOAD_CACHE["EW.html"] = {"version":"0a03d43b200e9dcb999a5d264252af494743999a4f10f20c03dedadee0f2b8b4","html":"<!DOCTYPE html>\n<html lang=\"zh-CN\" class=\"scroll-smooth\">\n<head>\n <meta charset=\"UTF-8\" />\n <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n <title>爱德华生命科学 Edwards Lifesciences (NYSE: EW) 深度研究报告：结构性心脏病全球霸主、TAVR 垄断红利与 TMTT 创新爆发</title>\n <!-- Tailwind CSS -->\n <script src=\"https://cdn.tailwindcss.com\"></script>\n <!-- Chart.js -->\n <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n <!-- Google Fonts: Inter + Noto Sans SC + JetBrains Mono -->\n <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600;700&family=Noto+Sans+SC:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n <script>\n tailwind.config = {\n darkMode: 'class',\n theme: {\n extend: {\n fontFamily: {\n sans: ['Inter', 'Noto Sans SC', 'system-ui', '-apple-system', 'sans-serif'],\n mono: ['JetBrains Mono', 'monospace'],\n },\n colors: {\n navy: {\n 950: '#070B14',\n 900: '#0F172A',\n 800: '#1E293B',\n 700: '#334155',\n },\n medblue: {\n 300: '#93C5FD',\n 400: '#60A5FA',\n 500: '#3B82F6',\n 600: '#2563EB',\n 700: '#1D4ED8',\n },\n emerald: {\n 400: '#34D399',\n 500: '#10B981',\n 600: '#059669',\n },\n teal: {\n 400: '#22D3EE',\n 500: '#06B6D4',\n 600: '#0891B2',\n }\n }\n }\n }\n }\n </script>\n\n <style>\n /* 自定义滚动条与机构研报细节排版 */\n ::-webkit-scrollbar {\n width: 6px;\n height: 6px;\n }\n ::-webkit-scrollbar-track {\n background: transparent;\n }\n ::-webkit-scrollbar-thumb {\n background: #94A3B8;\n border-radius: 3px;\n }\n .dark ::-webkit-scrollbar-thumb {\n background: #475569;\n }\n\n /* 打印友好优化 */\n @media print {\n #sidebar, #mobile-header, #theme-toggle-btn, .no-print {\n display: none !important;\n }\n main {\n margin-left: 0 !important;\n padding: 0 !important;\n }\n section {\n break-inside: avoid;\n }\n }\n\n /* 卡片悬浮微光与上移过渡 */\n .report-card {\n transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;\n }\n .report-card:hover {\n transform: translateY(-2px);\n }\n\n /* 侧边导航激活态：医疗蓝渐变标识底色 */\n .nav-link.active {\n background: linear-gradient(90deg, rgba(59, 130, 246, 0.24) 0%, rgba(16, 185, 129, 0.06) 100%);\n border-left: 3px solid #3B82F6;\n color: #FFFFFF;\n font-weight: 600;\n }\n </style>\n</head>\n<body class=\"bg-[#F8FAFC] text-[#1E293B] dark:bg-navy-950 dark:text-slate-100 antialiased selection:bg-medblue-500 selection:text-white transition-colors duration-200\">\n\n <!-- 顶部全局阅读进度条 -->\n <div class=\"fixed top-0 left-0 right-0 h-1 z-50 bg-slate-200/70 dark:bg-navy-800\">\n <div id=\"reading-progress\" class=\"h-full bg-gradient-to-r from-medblue-600 via-medblue-400 to-emerald-500 w-0 transition-all duration-150\"></div>\n </div>\n\n <!-- 移动端顶部导航栏 -->\n <header id=\"mobile-header\" class=\"lg:hidden sticky top-0 z-40 bg-navy-900 text-white border-b border-slate-800 px-4 py-3 flex items-center justify-between shadow-md\">\n <div class=\"flex items-center space-x-2.5\">\n <div class=\"w-8 h-8 rounded-lg bg-gradient-to-br from-medblue-400 to-medblue-600 flex items-center justify-center font-extrabold text-navy-950 text-xs shadow\">\n EW\n </div>\n <div>\n <div class=\"text-[11px] text-medblue-400 font-semibold tracking-wider uppercase\">NYSE: EW · Structural Heart</div>\n <div class=\"text-sm font-bold leading-tight\">爱德华生命科学 深度研究报告</div>\n </div>\n </div>\n <div class=\"flex items-center space-x-2\">\n <button onclick=\"toggleTheme()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-slate-300\" aria-label=\"切换阅读主题\">\n <svg class=\"w-5 h-5 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <svg class=\"w-5 h-5 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n </button>\n <button id=\"mobile-menu-btn\" onclick=\"toggleMobileMenu()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-white\" aria-label=\"打开目录\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 6h16M4 12h16M4 18h16\"/></svg>\n </button>\n </div>\n </header>\n\n <!-- 移动端折叠抽屉菜单 -->\n <div id=\"mobile-drawer\" class=\"fixed inset-0 z-50 hidden lg:hidden\">\n <div class=\"fixed inset-0 bg-slate-900/70 backdrop-blur-sm\" onclick=\"toggleMobileMenu()\"></div>\n <nav class=\"relative w-72 max-w-[80vw] h-full bg-navy-900 text-slate-300 flex flex-col justify-between p-5 overflow-y-auto shadow-2xl\">\n <div>\n <div class=\"flex items-center justify-between pb-4 border-b border-slate-800\">\n <span class=\"font-bold text-white text-base\">EW 研报目录导航</span>\n <button onclick=\"toggleMobileMenu()\" class=\"p-1.5 rounded-lg text-slate-400 hover:text-white\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M6 18L18 6M6 6l12 12\"/></svg>\n </button>\n </div>\n <ul class=\"mt-4 space-y-1.5 text-sm\">\n <li><a href=\"#sec-exec\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">00. 执行摘要与核心指标</a></li>\n <li><a href=\"#sec-biz\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">01. 业务架构与细分赛道拆解</a></li>\n <li><a href=\"#sec-moat\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">02. 核心技术壁垒与四重护城河</a></li>\n <li><a href=\"#sec-comp\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">03. 全球医疗器械巨头横向对比</a></li>\n <li><a href=\"#sec-fin\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">04. 财务健康与现金流复利推演</a></li>\n <li><a href=\"#sec-inv\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">05. 投资决策与三情景估值</a></li>\n <li><a href=\"#sec-kpi\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">06. 季度跟踪 KPI 核查清单</a></li>\n </ul>\n </div>\n <div class=\"pt-4 border-t border-slate-800 text-xs text-slate-400\">\n <p>全球医疗健康与创新器械研究组</p>\n <p class=\"mt-1\">数据基准：2026年11月 (Q3 26 / FY26E)</p>\n </div>\n </nav>\n </div>\n\n <!-- 桌面端左侧固定侧边导航栏 (宽 280px) -->\n <aside id=\"sidebar\" class=\"hidden lg:flex fixed top-0 left-0 bottom-0 w-[280px] bg-[#0F172A] text-slate-300 flex-col justify-between border-r border-slate-800 z-30 select-none\">\n <div>\n <!-- 机构品牌头 -->\n <div class=\"p-5 border-b border-slate-800/80\">\n <div class=\"flex items-center space-x-3\">\n <div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-medblue-400 via-medblue-500 to-medblue-600 flex items-center justify-center text-navy-950 font-extrabold text-base shadow-lg shadow-medblue-500/25\">\n EW\n </div>\n <div>\n <span class=\"inline-block text-[10px] font-bold tracking-widest uppercase text-medblue-400 bg-medblue-500/15 px-2 py-0.5 rounded\">NYSE: EW</span>\n <h2 class=\"text-white font-bold text-base mt-0.5 tracking-tight\">爱德华生命科学研报</h2>\n </div>\n </div>\n <p class=\"text-xs text-slate-400 mt-2.5 leading-relaxed\">\n 全球结构性心脏病创新之王 · TAVR 绝对霸主与 TMTT 赛道双轮驱动\n </p>\n </div>\n\n <!-- 股票实时快照徽章 -->\n <div class=\"px-5 py-3 bg-navy-950/70 border-b border-slate-800/80 space-y-1.5 text-xs\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">参考股价 (52周区间)</span>\n <span class=\"font-mono font-bold text-white\">~$105.80 <span class=\"text-slate-400 text-[10px]\">($74.7-$107.7)</span></span>\n </div>\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">2026E 调整后 EPS</span>\n <span class=\"font-mono font-bold text-emerald-400\">$2.97–$3.05 <span class=\"text-slate-400\">(+18%)</span></span>\n </div>\n <div class=\"flex items-center justify-between pt-1 border-t border-slate-800/70\">\n <span class=\"text-slate-400\">远期估值与现金</span>\n <span class=\"font-mono font-bold text-medblue-400\">~34.5x P/E · 现金 $31亿</span>\n </div>\n </div>\n\n <!-- 七大核心章节目录导航 -->\n <div class=\"px-3 py-3.5 overflow-y-auto max-h-[calc(100vh-310px)]\">\n <div class=\"px-3 mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500\">核心研究章节</div>\n <nav id=\"desktop-nav\" class=\"space-y-1 text-[13px]\">\n <a href=\"#sec-exec\" data-target=\"sec-exec\" class=\"nav-link active flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-medblue-400 mr-2\">00</span>执行摘要与核心指标</span>\n </a>\n <a href=\"#sec-biz\" data-target=\"sec-biz\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">01</span>业务架构与细分赛道拆解</span>\n </a>\n <a href=\"#sec-moat\" data-target=\"sec-moat\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">02</span>核心技术壁垒与四重护城河</span>\n </a>\n <a href=\"#sec-comp\" data-target=\"sec-comp\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">03</span>全球医疗器械巨头横向对比</span>\n </a>\n <a href=\"#sec-fin\" data-target=\"sec-fin\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">04</span>财务健康与现金流复利推演</span>\n </a>\n <a href=\"#sec-inv\" data-target=\"sec-inv\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">05</span>投资决策与三情景估值</span>\n </a>\n <a href=\"#sec-kpi\" data-target=\"sec-kpi\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">06</span>季度跟踪 KPI 核查清单</span>\n </a>\n </nav>\n </div>\n </div>\n\n <!-- 侧边栏底部工具栏 -->\n <div class=\"p-4 border-t border-slate-800/80 bg-navy-950/50 space-y-2.5\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-xs text-slate-400\">阅读模式切换</span>\n <button id=\"theme-toggle-btn\" onclick=\"toggleTheme()\" class=\"flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg bg-navy-800 hover:bg-navy-700 text-xs font-medium text-slate-200 border border-slate-700 transition cursor-pointer\">\n <svg class=\"w-3.5 h-3.5 text-medblue-400 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n <svg class=\"w-3.5 h-3.5 text-medblue-500 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <span class=\"dark:hidden\">深色护眼模式</span>\n <span class=\"hidden dark:inline\">机构亮色模式</span>\n </button>\n </div>\n <button onclick=\"window.print()\" class=\"w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg bg-gradient-to-r from-medblue-500 to-medblue-600 hover:from-medblue-600 hover:to-medblue-700 text-white text-xs font-extrabold transition shadow-sm cursor-pointer\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z\"/></svg>\n <span>打印 / 导出 PDF 研报</span>\n </button>\n </div>\n </aside>\n\n <!-- 主内容区 -->\n <main class=\"lg:ml-[280px] min-h-screen\">\n <div class=\"max-w-6xl mx-auto px-4 sm:px-8 py-8 lg:py-12 space-y-12\">\n\n <!-- =========================================================\n 00. Hero 研报封面区与执行摘要\n ========================================================= -->\n <section id=\"sec-exec\" class=\"scroll-mt-20\">\n <div class=\"flex flex-wrap items-center justify-between gap-3 mb-4 text-xs text-slate-500 dark:text-slate-400\">\n <div class=\"flex flex-wrap items-center gap-2\">\n <span class=\"px-2.5 py-1 rounded-md bg-medblue-500/15 text-medblue-700 dark:text-medblue-400 font-bold border border-medblue-500/30\">评级：买入 / 医疗创新与核心成长底仓</span>\n <span class=\"px-2.5 py-1 rounded-md bg-slate-200/70 dark:bg-navy-800 text-slate-700 dark:text-slate-300 font-medium\">周期：2026Q3 业绩双位数增长与指引上调期</span>\n </div>\n <div class=\"flex items-center space-x-3 font-mono\">\n <span>覆盖时间：2026年11月</span>\n <span>NYSE: EW</span>\n </div>\n </div>\n\n <div class=\"relative overflow-hidden rounded-2xl bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 text-white p-6 sm:p-10 shadow-xl border border-slate-700/70\">\n <div class=\"absolute inset-0 opacity-10 pointer-events-none\" style=\"background-image: radial-gradient(#3B82F6 1.2px, transparent 1.2px); background-size: 24px 24px;\"></div>\n <div class=\"relative z-10\">\n <div class=\"inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-medblue-500/20 border border-medblue-400/40 text-medblue-300 text-xs font-semibold mb-4\">\n <span class=\"w-2 h-2 rounded-full bg-medblue-400 animate-pulse\"></span>\n <span>CORE THESIS · TAVR 经导管主动脉瓣置换全球霸主 × TMTT 惊艳爆发（+44% YoY） × 78.5% 顶级毛利率</span>\n </div>\n <h1 class=\"text-2xl sm:text-4xl font-extrabold tracking-tight leading-tight text-white\">\n 爱德华生命科学 Edwards Lifesciences (NYSE: EW) 深度研究报告：结构性心脏病全球霸主、TAVR 垄断红利与 TMTT 创新爆发\n </h1>\n <p class=\"mt-4 text-sm sm:text-base text-slate-300 max-w-4xl leading-relaxed\">\n 爱德华生命科学交出了高质量的 <strong class=\"text-white\">2026Q3 财报</strong>：全球销售额实现 <strong class=\"text-medblue-300\">10.5% 同比增长（常定汇率 +11.2%）达 $17.2 亿</strong>，调整后 EPS 达 <strong class=\"text-emerald-400\">$0.80（同比大增 +19%）</strong>。其中，核心经导管主动脉瓣置换（TAVR）业务稳健增长 8.0% 至 $12.4 亿，而以二尖瓣和三尖瓣疗法（TMTT）为代表的第二增长曲线更实现惊艳的 <strong class=\"text-white\">44.0% 爆发式增长至 $2.07 亿</strong>。\n 管理层顺势上调全年财务展望：将 TMTT 销售指引调高至 $7.8–$7.9 亿，调整后 EPS 预期提升至 <strong class=\"text-medblue-300\">$2.97–$3.05（中位数同比增 18%）</strong>，充分印证了其在结构性心脏病领域的绝对垄断地位与强劲成长动能。\n </p>\n\n <div class=\"mt-6 pt-6 border-t border-slate-700/80 grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">顶级毛利率与壁垒</div>\n <div class=\"text-white font-semibold\">Q3 毛利率高达 78.5%，凭借专利瓣膜技术与独家临床数据构建无法逾越的医疗器械高墙</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">TMTT 业务井喷爆发</div>\n <div class=\"text-medblue-400 font-semibold\">PASCAL、EVOQUE 三尖瓣与二尖瓣系统高速放量，季度销售突破 $2.07 亿（同比 +44%）</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">现金流与资产负债表</div>\n <div class=\"text-emerald-400 font-semibold\">现金及等价物高达 $31 亿，债务仅 $6 亿，年内已执行约 $7 亿股票回购，财务极其稳健</div>\n </div>\n </div>\n </div>\n </div>\n\n <!-- 4个核心 KPI 卡片 -->\n <div class=\"grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mt-6\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>总市值与最新股价</span>\n <span class=\"p-1.5 rounded-lg bg-medblue-500/15 text-medblue-600 dark:text-medblue-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 7h8m0 0v8m0-8l-8 8-4-4-6 6\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$61.6B</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">~$105.80</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 全球医疗器械核心权重股，52 周交易区间在 $74.66 至 $107.69 之间。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>2026E 调整后 EPS 指引</span>\n <span class=\"p-1.5 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-2xl sm:text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$2.97–$3.05</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">+18% 中位数</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n Q3 调整后 EPS 达 $0.80 击败市场预期，全年盈利指引再度上调。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>Q3 毛利率 & TAVR 销售</span>\n <span class=\"p-1.5 rounded-lg bg-teal-500/15 text-teal-600 dark:text-teal-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">78.5%</span>\n <span class=\"text-xs font-bold text-teal-600 dark:text-teal-400 bg-teal-500/15 px-2 py-0.5 rounded\">TAVR $1.24B</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 核心经导管主动脉瓣置换业务保持 8%–8.8% 稳健增长，毛利率坚挺在近 79% 的顶尖水平。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>净现金与股票回购</span>\n <span class=\"p-1.5 rounded-lg bg-medblue-500/15 text-medblue-600 dark:text-medblue-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$3.1B</span>\n <span class=\"text-xs font-bold text-medblue-700 dark:text-medblue-400 bg-medblue-500/15 px-2 py-0.5 rounded\">回购 $700M</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 资产负债表拥有约 $31 亿现金及等价物，年内已执行 $7 亿回购，剩余 $13 亿回购授权。\n </p>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 一、 业务与收入架构 (Business & Revenue Architecture)\n ========================================================= -->\n <section id=\"sec-biz\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-medblue-600 dark:text-medblue-400\">Section 01 · Business & Revenue Architecture</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">一、 业务架构与细分赛道拆解：TAVR 基本盘稳如磐石，TMTT 驱动第二成长曲线</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">FY26E 全球销售额超 $68 亿 · 结构性心脏病全球领导者</span>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n <div class=\"lg:col-span-7 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\" id=\"biz-chart-title\">2022–2026E 全球净营收与 TAVR/TMTT 分板块演进</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\" id=\"biz-chart-sub\">TAVR 构成绝对基本盘，TMTT（二尖瓣与三尖瓣疗法）实现爆发式高增速</p>\n </div>\n <div class=\"inline-flex rounded-lg bg-slate-100 dark:bg-navy-800 p-1 text-xs no-print\">\n <button onclick=\"switchBizChart('revenue_mix')\" id=\"btn-chart-rev\" class=\"px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-medblue-600 dark:text-medblue-400 shadow-sm transition cursor-pointer\">视图A：营收板块结构演进</button>\n <button onclick=\"switchBizChart('metrics_split')\" id=\"btn-chart-met\" class=\"px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer\">视图B：Q3 业务线增速与指标拆解</button>\n </div>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"bizArchitectureChart\"></canvas>\n </div>\n </div>\n\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">2026Q3 三大核心经营与临床里程碑</h3>\n <ul class=\"space-y-4 text-sm\">\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-medblue-500/15 text-medblue-600 dark:text-medblue-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">TAVR 销售额达 $12.4 亿（常定汇率 +8.8%）</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 得益于“Progress Trial”等重磅临床数据支持（证明早期介入中度主动脉瓣狭窄AS患者优于临床监视），全球临床手术量和早期筛查率持续超预期。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">TMTT 业务同比大增 +45.6%（常定汇率）突破 $2.07 亿</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n PASCAL 修复系统与 EVOQUE 三尖瓣置换系统在全球范围内加速商业化放量，CLASP II TR 临床试验展现卓越生活质量改善。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-teal-500/15 text-teal-600 dark:text-teal-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">外科心脏瓣膜与 RESILIA 组织技术表现稳健</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 10 年长期临床随访数据证实 RESILIA 组织抗钙化与超长耐用性，持续巩固外科瓣膜（Surgical Structural Heart）市场份额。\n </p>\n </div>\n </li>\n </ul>\n </div>\n <div class=\"mt-5 pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-xs\">\n <span class=\"text-slate-500 dark:text-slate-400\">长期战略成长锚点</span>\n <span class=\"font-bold text-medblue-600 dark:text-medblue-400\">TAVR 适应症扩大 + TMTT 爆发双轮驱动</span>\n </div>\n </div>\n </div>\n\n <!-- 四大业务板块详细卡片矩阵 -->\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-5\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-medblue-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-medblue-500/15 text-medblue-700 dark:text-medblue-400 text-xs font-bold\">绝对现金牛支柱 · 占营收 ~72%</span>\n <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">Q3 销售 $1.24B (+8.8%)</span>\n </div>\n <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">1. 经导管主动脉瓣置换 (TAVR)</h3>\n <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n 爱德华的 SAPIEN 瓣膜系列是全球经导管主动脉瓣置换（TAVR）的绝对行业金标准。凭借极低的微创手术风险和丰富的长期临床数据，持续引领全球重度及中度主动脉瓣狭窄患者的治疗范式革新。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-[11px] font-mono text-slate-500 dark:text-slate-400\">\n <span>全球主导级市场份额</span>\n <span class=\"text-medblue-600 dark:text-medblue-400 font-semibold\">受益于无症状及中度AS适应症扩大</span>\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-emerald-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-emerald-500/15 text-emerald-700 dark:text-emerald-400 text-xs font-bold\">高增长第二引擎 · 季度破 $2.07亿</span>\n <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">同比大增 +45.6%</span>\n </div>\n <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">2. 二尖瓣与三尖瓣疗法 (TMTT)</h3>\n <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n 涵盖 PASCAL 经导管二尖瓣/三尖瓣修复系统及全球首创的 EVOQUE 经导管三尖瓣置换系统。该板块正在经历爆发式放量，年销售指引已上调至 $7.8–$7.9 亿，成为公司中长期最高速的增长极。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-[11px] font-mono text-slate-500 dark:text-slate-400\">\n <span>年指引上调至 $780M-$790M</span>\n <span class=\"text-emerald-600 dark:text-emerald-400 font-semibold\">填补全球庞大未满足临床需求</span>\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-teal-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-teal-500/15 text-teal-700 dark:text-teal-400 text-xs font-bold\">传统基本盘 · RESILIA 组织技术</span>\n <span class=\"font-mono text-xs font-bold text-teal-600 dark:text-teal-400\">10年长期数据支撑</span>\n </div>\n <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">3. 外科结构性心脏病 (Surgical Structural Heart)</h3>\n <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n 提供高端外科心脏瓣膜及生物瓣膜产品。搭载突破性 RESILIA 牛心包组织技术的瓣膜产品展现出卓越的抗钙化耐久性（10年关键临床数据完美发布），在全球外科手术中保持稳固的高端领先地位。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-[11px] font-mono text-slate-500 dark:text-slate-400\">\n <span>RESILIA 组织技术全球领先</span>\n <span class=\"text-teal-600 dark:text-teal-400 font-semibold\">外科瓣膜领域高端现金牛</span>\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-indigo-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-indigo-500/15 text-indigo-700 dark:text-indigo-400 text-xs font-bold\">重症监护与微创监测 · 高黏性</span>\n <span class=\"font-mono text-xs font-bold text-indigo-600 dark:text-indigo-400\">智能血流动力学</span>\n </div>\n <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">4. 重症监护与血流动力学监测 (Critical Care)</h3>\n <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n 提供先进的临床血流动力学监测传感器和智能决策算法软件（如 Acumen Hypotension Prediction Index），广泛应用于全球各大医院的手术室与重症监护室（ICU），为术中患者安全保驾护航。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-[11px] font-mono text-slate-500 dark:text-slate-400\">\n <span>医院手术室与ICU标配</span>\n <span class=\"text-indigo-600 dark:text-indigo-400 font-semibold\">提供高粘性临床生态系统</span>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 二、 核心技术壁垒与四重护城河 (Economic Moat)\n ========================================================= -->\n <section id=\"sec-moat\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 02 · Technological Moats & Economic Barriers</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">二、 核心技术壁垒与四重护城河：临床证据高墙、瓣膜专利与 78.5% 毛利率</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">护城河评级：极宽 (Wide Economic Moat)</span>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-medblue-500/15 text-medblue-600 dark:text-medblue-400 flex items-center justify-center font-bold text-sm\">01</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">无可辩驳的长期临床证据与医生信任</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 心脏瓣膜植入人体需要长达十几年甚至数十年的安全性和耐用性数据验证。爱德华历经几十年积累的庞大临床试验数据库（如 SAPIEN 系列与 RESILIA 组织10年数据）是全球心胸外科医生最信赖的指南，新进入者几乎无法在短期内跨越。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 flex items-center justify-center font-bold text-sm\">02</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">高密度的知识产权与核心瓣膜专利网</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 从牛心包抗钙化处理工艺、球囊膨胀式导管输送系统到二尖瓣/三尖瓣修复夹合技术，爱德华在全球范围内拥有数千项严密的核心专利保护，构筑了坚固的知识产权护城河。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-teal-500/15 text-teal-600 dark:text-teal-400 flex items-center justify-center font-bold text-sm\">03</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">全球医院导管室与心脏外科医师高粘性生态</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n TAVR 和 TMTT 手术高度依赖专业的心脏团队（Heart Team）培训与临床支持。爱德华的专业技术代表常年进驻全球各大顶级心脏中心，与外科医生深度绑定，形成极高的客户转移成本。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 flex items-center justify-center font-bold text-sm\">04</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">78.5% 顶级毛利率支撑的高强度研发投入</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 接近 80% 的毛利率转化为每年数十亿美元的自由现金流，其中相当一部分持续投入到下一代瓣膜、人工智能医学影像及结构性心脏病前沿创新研发中，形成“技术领先-高毛利-再研发”的强者恒强飞轮。\n </p>\n </div>\n </div>\n\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">医疗器械与心血管巨头五维护城河雷达图</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">爱德华 (EW) vs 美敦力 (MDT) vs 波士顿科学 (BSX)（满分 10 分）</p>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"moatRadarChart\"></canvas>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 三、 全球医疗器械巨头横向对比 (Competitive Landscape)\n ========================================================= -->\n <section id=\"sec-comp\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-3\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-medblue-600 dark:text-medblue-400\">Section 03 · Global MedTech Competitive Landscape</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">三、 全球医疗器械巨头横向对比：专注结构性心脏病的高成长与高毛利典范</h2>\n </div>\n <div class=\"flex flex-wrap gap-1.5 text-xs no-print\" id=\"comp-filter-group\">\n <button onclick=\"filterCompetitors('all')\" data-filter=\"all\" class=\"comp-filter-btn active px-3 py-1.5 rounded-lg font-semibold bg-medblue-500 text-white shadow-sm transition cursor-pointer\">全部巨头</button>\n <button onclick=\"filterCompetitors('cardio')\" data-filter=\"cardio\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition cursor-pointer\">心血管与瓣膜同行</button>\n <button onclick=\"filterCompetitors('diversified')\" data-filter=\"diversified\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition cursor-pointer\">综合型医疗器械巨头</button>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden\">\n <div class=\"overflow-x-auto\">\n <table class=\"w-full text-left border-collapse\">\n <thead>\n <tr class=\"bg-slate-100/80 dark:bg-navy-800/80 border-b border-slate-200 dark:border-slate-700 text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-300\">\n <th class=\"py-4 px-5 min-w-[180px]\">企业名称与代码</th>\n <th class=\"py-4 px-4 min-w-[130px]\">核心业务聚焦</th>\n <th class=\"py-4 px-4 min-w-[140px]\">结构性心脏病进展</th>\n <th class=\"py-4 px-4 min-w-[100px]\">远期 P/E</th>\n <th class=\"py-4 px-4 min-w-[115px]\">远期股息率</th>\n <th class=\"py-4 px-4 min-w-[115px]\">毛利率</th>\n <th class=\"py-4 px-5 min-w-[230px]\">核心优劣势与竞合定位评估</th>\n </tr>\n </thead>\n <tbody class=\"divide-y divide-slate-200 dark:divide-slate-800 text-xs sm:text-sm\" id=\"comp-table-body\">\n <tr data-category=\"cardio\" class=\"bg-medblue-500/5 dark:bg-medblue-500/10 font-medium\">\n <td class=\"py-4 px-5\">\n <div class=\"flex items-center space-x-2\">\n <span class=\"px-2 py-0.5 rounded bg-medblue-500 text-white text-[10px] font-extrabold\">核心研究标的</span>\n <span class=\"font-bold text-slate-900 dark:text-white\">爱德华生命科学 (EW)</span>\n </div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Edwards Lifesciences</div>\n </td>\n <td class=\"py-4 px-4 font-semibold text-slate-900 dark:text-white\">结构性心脏病 (TAVR/TMTT)</td>\n <td class=\"py-4 px-4\">\n <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-semibold bg-medblue-500/15 text-medblue-700 dark:text-medblue-400\">TAVR霸主 & TMTT大爆发</span>\n </td>\n <td class=\"py-4 px-4 font-mono font-bold text-slate-900 dark:text-white\">~34.5x</td>\n <td class=\"py-4 px-4 font-mono font-bold text-slate-400\">无分红 (专注于回购)</td>\n <td class=\"py-4 px-4 font-mono font-bold text-emerald-600 dark:text-emerald-400\">~78.5%</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>纯粹的瓣膜与结构性心脏病专家：</strong>高度专注带来极高的毛利与研发效率，专业壁垒极其深厚，成长确定性极高。\n </td>\n </tr>\n\n <tr data-category=\"diversified\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">美敦力 (MDT)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Medtronic plc</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">综合医疗器械 (心律/脊柱/外科)</td>\n <td class=\"py-4 px-4\">\n <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-emerald-500/15 text-emerald-700 dark:text-emerald-400\">Evolut TAVR 强劲竞争对手</span>\n </td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~16.5x</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~3.20%</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~65.0%</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>全球综合医疗器械巨头：</strong>业务线极其庞大，旗下 Evolut TAVR 系统与爱德华形成双寡头竞争，但整体增速和利润率逊于专注心血管的爱德华。\n </td>\n </tr>\n\n <tr data-category=\"cardio\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">波士顿科学 (BSX)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Boston Scientific</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">心血管介入与电生理/内窥镜</td>\n <td class=\"py-4 px-4\">\n <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-teal-500/15 text-teal-700 dark:text-teal-400\">ACURATE neo 及瓣膜布局</span>\n </td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~31.0x</td>\n <td class=\"py-4 px-4 font-mono text-slate-500 dark:text-slate-400\">0.0%</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~69.0%</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>心血管介入全能选手：</strong>在电生理和周围血管领域极强，近年来在结构性心脏病领域持续追赶，整体估值与成长性与爱德华相近。\n </td>\n </tr>\n\n <tr data-category=\"diversified\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">雅培 (ABT)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Abbott Laboratories</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">体外诊断/糖尿病(FreeStyle)/心血管</td>\n <td class=\"py-4 px-4\">\n <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-amber-500/15 text-amber-700 dark:text-amber-400\">MitraClip 二尖瓣修复系统</span>\n </td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~22.0x</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~1.90%</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~56.0%</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>顶级医疗防御标坦：</strong>旗下 MitraClip 曾长期统治二尖瓣微创修复市场，与爱德华在结构性心脏病赛道展开激烈角逐。\n </td>\n </tr>\n </tbody>\n </table>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">全球医疗器械巨头毛利率（Gross Margin）与远期 P/E 估值对比</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400\">爱德华凭借高端瓣膜专精定位，以 78.5% 的毛利率稳居医疗器械行业塔尖</p>\n </div>\n <span class=\"text-xs font-semibold text-medblue-700 dark:text-medblue-400 bg-medblue-500/15 px-2.5 py-1 rounded\">78.5% 毛利率断层领先</span>\n </div>\n <div class=\"relative h-64 w-full\">\n <canvas id=\"compMarginChart\"></canvas>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 四、 财务健康与现金流模型 (Financial Health & FCF)\n ========================================================= -->\n <section id=\"sec-fin\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 04 · Financial Health & Cash Flow Model</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">四、 财务健康度与现金流模型：$31亿现金储备与股票回购增厚复利</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">资产负债表极度纯净 · 净现金结构与高额回购授权</span>\n </div>\n\n <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-medblue-600 dark:text-medblue-400 uppercase\">Gross Profit Margin</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">78.5%</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 核心瓣膜产品具备极强的定价权与专利壁垒，毛利率常年维持在近 80% 的医疗器械行业最高水准。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 uppercase\">Cash & Equivalents</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">~$3.1B</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 截至 Q3 末持有现金及短期投资约 $31 亿，总债务仅约 $6 亿，属于零净债务（Net Cash）的优质资产。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-teal-600 dark:text-teal-400 uppercase\">Share Repurchases</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">~$700M (YTD)</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 前三季度已执行约 $7 亿股票回购，尚有约 $1.3 亿回购授权额度随时准备在股价回调时进场。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-indigo-600 dark:text-indigo-400 uppercase\">Adjusted EPS Growth</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">+18% (YoY)</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 2026 全年调整后 EPS 指引中位数实现 18% 同比强劲增长，盈利兑现能力不断超越市场共识。\n </p>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">2021–2026E 全球净营收与调整后 EPS 增长演进矩阵</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400\">营收稳步迈向 $7B 关卡，每股收益在回购与高毛利驱动下持续稳健上行</p>\n </div>\n <span class=\"text-xs font-mono font-bold text-medblue-700 dark:text-medblue-400 bg-medblue-500/15 px-2.5 py-1 rounded\">双位数复合增长态势延续</span>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"valEvolutionChart\"></canvas>\n </div>\n </div>\n\n <!-- 模拟计算器 -->\n <div class=\"bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 rounded-2xl p-6 sm:p-8 text-white border border-slate-700 shadow-xl space-y-6 no-print\">\n <div class=\"flex flex-col md:flex-row md:items-center justify-between gap-3 pb-4 border-b border-slate-700/80\">\n <div>\n <div class=\"inline-flex items-center space-x-2 text-xs font-mono uppercase tracking-wider text-medblue-400 font-bold\">\n <span>MEDTECH COMPOUNDING ENGINE · 医疗成长股复利模拟器</span>\n </div>\n <h3 class=\"text-lg sm:text-xl font-bold text-white mt-1\">爱德华生命科学 (EW) 长期持仓资本增值与回购复利模拟器</h3>\n <p class=\"text-xs text-slate-400 mt-0.5\">基准参数：当前参考股价 $105.80 | 预计 EPS 复合增长率 | 支持不同地区美股税务情景测算</p>\n </div>\n <label class=\"inline-flex items-center space-x-2.5 px-3.5 py-2 rounded-xl bg-medblue-500/15 border border-medblue-400/30 text-xs font-semibold text-medblue-300 cursor-pointer shrink-0\">\n <input type=\"checkbox\" id=\"drip-toggle\" checked onchange=\"updateDividendSimulator()\" class=\"w-4 h-4 rounded accent-[#3B82F6] cursor-pointer\">\n <span>开启资本再投资 / 回购增厚模拟</span>\n </label>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n <div class=\"lg:col-span-5 space-y-4 text-xs\">\n <div>\n <div class=\"flex justify-between mb-1.5\">\n <span class=\"text-slate-300 font-medium\">初始投入本金 (USD)</span>\n <span id=\"sim-principal-label\" class=\"font-mono font-bold text-white text-sm\">$50,000</span>\n </div>\n <input id=\"sim-principal\" type=\"range\" min=\"10000\" max=\"300000\" step=\"10000\" value=\"50000\" oninput=\"updateDividendSimulator()\" class=\"w-full accent-[#3B82F6] cursor-pointer\">\n </div>\n\n <div>\n <div class=\"flex justify-between mb-1.5\">\n <span class=\"text-slate-300 font-medium\">长期持有年限 (Years)</span>\n <span id=\"sim-years-label\" class=\"font-mono font-bold text-white text-sm\">10 年</span>\n </div>\n <input id=\"sim-years\" type=\"range\" min=\"1\" max=\"20\" step=\"1\" value=\"10\" oninput=\"updateDividendSimulator()\" class=\"w-full accent-[#3B82F6] cursor-pointer\">\n </div>\n\n <div>\n <div class=\"flex justify-between mb-1.5\">\n <span class=\"text-slate-300 font-medium\">年均 EPS 与市值复合增长率 (预期 12-15%)</span>\n <span id=\"sim-growth-label\" class=\"font-mono font-bold text-emerald-400 text-sm\">13.0%</span>\n </div>\n <input id=\"sim-growth\" type=\"range\" min=\"5\" max=\"20\" step=\"0.5\" value=\"13.0\" oninput=\"updateDividendSimulator()\" class=\"w-full accent-[#10B981] cursor-pointer\">\n </div>\n\n <div class=\"pt-1\">\n <div class=\"text-slate-300 font-medium mb-2\">持股账户税务情景：</div>\n <div class=\"grid grid-cols-3 gap-2\" id=\"tax-btn-group\">\n <button type=\"button\" onclick=\"setTaxRate(0)\" data-tax=\"0\" class=\"tax-btn px-2 py-2 rounded-lg text-[11px] font-medium bg-navy-950/70 text-slate-300 border border-slate-700 hover:border-medblue-400 transition cursor-pointer\">\n 0% 免税账户<br><span class=\"text-[10px] text-slate-400\">IRA/养老金</span>\n </button>\n <button type=\"button\" onclick=\"setTaxRate(0.15)\" data-tax=\"0.15\" class=\"tax-btn active px-2 py-2 rounded-lg text-[11px] font-bold bg-medblue-500 text-white border border-medblue-400 shadow transition cursor-pointer\">\n 15% 标准资本利得税<br><span class=\"text-[10px] text-white\">一般经纪账户</span>\n </button>\n <button type=\"button\" onclick=\"setTaxRate(0.30)\" data-tax=\"0.3\" class=\"tax-btn px-2 py-2 rounded-lg text-[11px] font-medium bg-navy-950/70 text-slate-300 border border-slate-700 hover:border-medblue-400 transition cursor-pointer\">\n 30% 最高税率<br><span class=\"text-[10px] text-slate-400\">跨境标准税率</span>\n </button>\n </div>\n </div>\n </div>\n\n <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末预计总资产估值</div>\n <div id=\"sim-final-value\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-white mt-1.5\">$180,240</div>\n <div id=\"sim-total-return\" class=\"text-xs font-semibold text-emerald-400 mt-1.5\">累计税后总回报 +260.5%</div>\n </div>\n\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末预计持仓市值资本增值</div>\n <div id=\"sim-annual-div\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-medblue-400 mt-1.5\">$130,240</div>\n <div id=\"sim-monthly-div\" class=\"text-xs text-slate-400 mt-1.5\">年化复合增值回报</div>\n </div>\n\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">隐含复合年化收益率 (CAGR)</div>\n <div id=\"sim-yoc\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-teal-400 mt-1.5\">13.00%</div>\n <div class=\"text-xs text-slate-400 mt-1.5\">基于所设定的成长假设</div>\n </div>\n\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末预计持仓总股数</div>\n <div id=\"sim-cum-div\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-emerald-400 mt-1.5\">472.6 股</div>\n <div id=\"sim-shares-end\" class=\"text-xs text-slate-400 mt-1.5\">起始持仓股数：472.6 股 (股价 $105.8)</div>\n </div>\n </div>\n </div>\n </div>\n\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-6\">\n <div class=\"bg-emerald-50/70 dark:bg-emerald-950/20 rounded-2xl p-6 border border-emerald-200 dark:border-emerald-800/60\">\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"font-bold text-emerald-700 dark:text-emerald-400 text-base\">多头核心论点 (Bull Thesis)</span>\n <span class=\"text-xs font-semibold px-2.5 py-0.5 rounded-full bg-emerald-500/15 text-emerald-700 dark:text-emerald-300\">结构性老龄化 + TMTT 爆发</span>\n </div>\n <ul class=\"space-y-2 text-xs sm:text-sm text-slate-700 dark:text-slate-300\">\n <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>全球老龄化带来的结构性心脏病刚需：</strong>随着全球人口预期寿命延长，主动脉瓣狭窄及二尖瓣/三尖瓣疾病患者基数持续膨胀，临床治疗需求刚性。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>TMTT 业务打开数百亿美元全新天花板：</strong>PASCAL 与 EVOQUE 系统的放量使爱德华从单一 TAVR 垄断者进化为全品类结构性心脏病巨头。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>接近 79% 的超高毛利与强劲现金流：</strong>极致的专注度和专利壁垒赋予其极强的抗通胀与盈利兑现能力。</span></li>\n </ul>\n </div>\n\n <div class=\"bg-rose-50/70 dark:bg-rose-950/20 rounded-2xl p-6 border border-rose-200 dark:border-rose-800/60\">\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"font-bold text-rose-700 dark:text-rose-400 text-base\">空头担忧论点 (Bear Thesis)</span>\n <span class=\"text-xs font-semibold px-2.5 py-0.5 rounded-full bg-rose-500/15 text-rose-700 dark:text-rose-300\">估值倍数较高 + 同业竞争</span>\n </div>\n <ul class=\"space-y-2 text-xs sm:text-sm text-slate-700 dark:text-slate-300\">\n <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>估值容错率相对有限：</strong>Forward P/E 处于 ~34x 相对高位，一旦某季度 TAVR 增速出现短期波动或临床数据不及预期，容易引发估值回调。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>来自美敦力与波士顿科学的竞争压力：</strong>美敦力 Evolut 系统的持续迭代以及波士顿科学在微创瓣膜领域的追赶，对市占率构成潜在摩擦。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>医疗系统预算与医院手术产能瓶颈：</strong>全球部分地区医院导管室医护人员短缺或医保支付政策收紧可能阶段性限制手术量上限。</span></li>\n </ul>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 五、 投资决策与三情景估值框架 (Investment Decision & Valuation)\n ========================================================= -->\n <section id=\"sec-inv\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-medblue-600 dark:text-medblue-400\">Section 05 · Investment Decision & Valuation Framework</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">五、 投资决策与风险配置：三情景目标价与核心成长标的配置策略</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">配置建议：医疗创新核心底仓 · 逢大盘回调分批长线买入</span>\n </div>\n\n <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-emerald-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 text-xs font-bold\">牛市情景 (Bull Case)</span>\n <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">概率：25%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">38.0x–42.0x P/E ($125–$140)</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>TAVR 适应症成功拓展至早期无症状主动脉瓣狭窄患者，TMTT 销售增速超预期突破 $10 亿大关，市场全面上调其长期估值中枢。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-emerald-600 dark:text-emerald-400\">\n 潜在年化总回报：+16% 至 +24%\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-medblue-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-medblue-500/15 text-medblue-700 dark:text-medblue-400 text-xs font-bold\">基准情景 (Base Case)</span>\n <span class=\"font-mono text-xs font-bold text-medblue-600 dark:text-medblue-400\">概率：60%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">32.0x–35.0x P/E ($105–$115)</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>2026–2028 年维持 10% 左右营收复合增长，EPS 保持 13%–15% 稳健增长，叠加回购稳步注销股份，估值在合理中枢健康运行。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-medblue-600 dark:text-medblue-400\">\n 稳健年化总回报：+11% 至 +14%\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-rose-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-rose-500/15 text-rose-600 dark:text-rose-400 text-xs font-bold\">熊市情景 (Bear Case)</span>\n <span class=\"font-mono text-xs font-bold text-rose-600 dark:text-rose-400\">概率：15%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">26.0x–28.0x P/E ($85–$92)</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>宏观医疗板块遭遇政策打压或竞品分流导致 TAVR 增速放缓，引发高估值标的杀估值回调。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-rose-600 dark:text-rose-400\">\n 潜在回撤：-15% 至 -22%（优质创新医疗资产的黄金逢低吸纳点）\n </div>\n </div>\n </div>\n\n <div class=\"bg-gradient-to-r from-navy-900 to-navy-800 rounded-2xl p-6 text-white border border-slate-700 shadow-md\">\n <h3 class=\"text-base font-bold text-medblue-400 mb-4 flex items-center space-x-2\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n <span>机构级投资组合配置纪律与创新医疗策略</span>\n </h3>\n <div class=\"grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-white mb-1\">1. 医疗创新核心配置</div>\n <p class=\"text-slate-300 leading-relaxed\">\n <strong>爱德华生命科学 (EW)</strong> 具备不可替代的瓣膜专精优势与高毛利率，是科技成长组合中兼具防御与高弹性的优质医疗核心标的。\n </p>\n </div>\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-medblue-400 mb-1\">2. 价格触发与分批建仓纪律</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 当前股价位于 ~$105.80 附近，估值较为合理。建议以底仓长期持有，若遇市场整体回调使股价回踩 <strong>$88–$95 区间</strong>则果断增持。\n </p>\n </div>\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-emerald-400 lean-relaxed\">3. 资产负债表与回购安全垫</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 拥有 $31 亿净现金和高达 78.5% 的毛利率，叠加源源不断的回购注销，为长期股东锁定了极高的成长确定性。\n </p>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 六、 季度基本面跟踪 KPI 交互式核查清单 (Checklist)\n ========================================================= -->\n <section id=\"sec-kpi\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 06 · Quarterly Fundamental Tracking KPIs</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">六、 季度基本面跟踪 KPI 交互式核查清单（Checklist）</h2>\n </div>\n <div class=\"flex items-center space-x-2 no-print\">\n <span id=\"kpi-progress-badge\" class=\"px-3 py-1 rounded-full bg-medblue-500/15 text-medblue-700 dark:text-medblue-400 text-xs font-bold\">已核查 3 / 6 项 (50%)</span>\n <button onclick=\"resetKpiChecklist()\" class=\"px-2.5 py-1 rounded-lg bg-slate-200/80 dark:bg-navy-800 hover:bg-slate-300 dark:hover:bg-navy-700 text-xs font-medium text-slate-700 dark:text-slate-300 transition cursor-pointer\">重置清单</button>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">\n 点击勾选季度财报中已验证达标的经营指标（勾选状态自动本地保存），持续校验爱德华生命科学的技术壁垒与成长动能：\n </p>\n\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-3.5\" id=\"kpi-checklist\">\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-1\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#3B82F6] focus:ring-medblue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">1. TAVR 销售额是否维持 8%–10% 稳定常定汇率增速</span>\n <span class=\"text-[11px] font-mono text-medblue-600 dark:text-medblue-400 font-semibold shrink-0\">基本盘稳健锚</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 2026Q3 TAVR 销售额达 $12.4 亿（常定汇率 +8.8%），需确认全球各大心脏中心手术量是否持续稳健。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-2\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#3B82F6] focus:ring-medblue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">2. TMTT 业务季度销售能否持续超预期并达成 $7.8亿+ 全年目标</span>\n <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">第二增长引擎</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n Q3 TMTT 销售突破 $2.07 亿（同比 +45.6%），需核查 PASCAL 与 EVOQUE 三尖瓣系统的全球放量速度。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-3\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#3B82F6] focus:ring-medblue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">3. 公司毛利率是否稳守 77%–79% 行业顶尖高位</span>\n <span class=\"text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold shrink-0\">专利定价权护城河</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 监督制造供应链成本与产品组合对整体毛利率（Q3 达 78.5%）的支撑力度。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-4\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#3B82F6] focus:ring-medblue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">4. 临床试验与前沿监管进展（如 Progress Trial 适应症扩大落地）</span>\n <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">长期天花板突破</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 跟踪中度主动脉瓣狭窄及无症状患者的 FDA 审批与临床指南更新进展。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-5\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#3B82F6] focus:ring-medblue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">5. 资产负债表现金储备与股票回购执行进度</span>\n <span class=\"text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold shrink-0\">股东回报与资本配置</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 监督 $31 亿现金使用效率及剩余 $1.3 亿回购授权的落地节奏。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-6\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#3B82F6] focus:ring-medblue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">6. 全球主要市场（美、欧、亚）手术量与医院端渗透率数据</span>\n <span class=\"text-[11px] font-mono text-medblue-600 dark:text-medblue-400 font-semibold shrink-0\">区域放量晴雨表</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 关注各主要国家和地区微创心脏手术渗透率及医生培训中心拓展情况。\n </p>\n </div>\n </label>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 页脚免责声明\n ========================================================= -->\n <footer class=\"pt-8 border-t border-slate-200 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400 space-y-2 pb-10\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 font-semibold text-slate-700 dark:text-slate-300\">\n <span>爱德华生命科学 Edwards Lifesciences Corp. (NYSE: EW) 深度商业与投资价值分析报告 · 机构研究框架版</span>\n <span>数据基准：2026Q3 财报及 2026 年 11 月市场一致预期 (FY26E)</span>\n </div>\n <p class=\"leading-relaxed\">\n <strong>免责声明：</strong>本深度研究报告基于爱德华生命科学公开财务报告（10-Q/10-K）、2026Q3 业绩电话会议披露数据及全球结构性心脏病医疗器械行业调研资料整理生成，旨在提供结构化的产业分析与医疗成长资产估值框架。报告中涉及的盈利预测、TAVR/TMTT 销售测算、三情景目标价及资本增值模拟均基于特定假设条件推演，不构成任何证券买卖建议、税务规划意见或收益承诺。\n </p>\n </footer>\n\n </div>\n </main>\n\n <!-- 交互脚本与 Chart.js -->\n <script>\n function toggleTheme() {\n const html = document.documentElement;\n html.classList.toggle('dark');\n updateChartsTheme();\n }\n\n function toggleMobileMenu() {\n const drawer = document.getElementById('mobile-drawer');\n drawer.classList.toggle('hidden');\n }\n\n const sections = document.querySelectorAll('section[id]');\n const navLinks = document.querySelectorAll('#desktop-nav .nav-link');\n\n window.addEventListener('scroll', () => {\n const scrollTop = window.scrollY;\n const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n const scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;\n document.getElementById('reading-progress').style.width = `${Math.min(100, Math.max(0, scrollPercent))}%`;\n\n let currentId = 'sec-exec';\n sections.forEach(sec => {\n const top = sec.offsetTop - 160;\n if (scrollTop >= top) {\n currentId = sec.getAttribute('id');\n }\n });\n\n navLinks.forEach(link => {\n link.classList.remove('active');\n const numSpan = link.querySelector('span span');\n if (numSpan) {\n numSpan.classList.remove('text-medblue-400');\n numSpan.classList.add('text-slate-500');\n }\n if (link.dataset.target === currentId) {\n link.classList.add('active');\n if (numSpan) {\n numSpan.classList.remove('text-slate-500');\n numSpan.classList.add('text-medblue-400');\n }\n }\n });\n });\n\n function filterCompetitors(category) {\n document.querySelectorAll('.comp-filter-btn').forEach(btn => {\n if (btn.dataset.filter === category) {\n btn.classList.add('bg-medblue-500', 'text-white', 'font-semibold', 'shadow-sm');\n btn.classList.remove('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n } else {\n btn.classList.remove('bg-medblue-500', 'text-white', 'font-semibold', 'shadow-sm');\n btn.classList.add('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n }\n });\n\n const rows = document.querySelectorAll('#comp-table-body tr');\n rows.forEach(row => {\n const rowCat = row.dataset.category;\n if (category === 'all' || rowCat === category) {\n row.style.display = '';\n } else {\n row.style.display = 'none';\n }\n });\n }\n\n let currentTaxRate = 0.15;\n\n function setTaxRate(rate) {\n currentTaxRate = rate;\n document.querySelectorAll('#tax-btn-group .tax-btn').forEach(btn => {\n const btnRate = parseFloat(btn.dataset.tax);\n if (Math.abs(btnRate - rate) < 0.001) {\n btn.className = 'tax-btn active px-2 py-2 rounded-lg text-[11px] font-bold bg-medblue-500 text-white border border-medblue-400 shadow transition cursor-pointer';\n } else {\n btn.className = 'tax-btn px-2 py-2 rounded-lg text-[11px] font-medium bg-navy-950/70 text-slate-300 border border-slate-700 hover:border-medblue-400 transition cursor-pointer';\n }\n });\n updateDividendSimulator();\n }\n\n function updateDividendSimulator() {\n const principal = parseFloat(document.getElementById('sim-principal').value);\n const years = parseInt(document.getElementById('sim-years').value, 10);\n const growthPct = parseFloat(document.getElementById('sim-growth').value);\n\n document.getElementById('sim-principal-label').textContent = '$' + principal.toLocaleString('en-US');\n document.getElementById('sim-years-label').textContent = years + ' 年';\n document.getElementById('sim-growth-label').textContent = growthPct.toFixed(1) + '%';\n\n const initPrice = 105.80;\n const g = growthPct / 100;\n const initialShares = principal / initPrice;\n\n let finalVal = principal * Math.pow(1 + g, years);\n const totalGain = finalVal - principal;\n const netGain = totalGain * (1 - currentTaxRate);\n const netFinalVal = principal + netGain;\n\n const totalReturnPct = ((netFinalVal - principal) / principal) * 100;\n const annualGain = netFinalVal - principal;\n\n document.getElementById('sim-final-value').textContent = '$' + Math.round(netFinalVal).toLocaleString('en-US');\n document.getElementById('sim-total-return').textContent = `累计税后总回报 +${totalReturnPct.toFixed(1)}%`;\n document.getElementById('sim-annual-div').textContent = '+$' + Math.round(annualGain / years).toLocaleString('en-US') + '/年';\n document.getElementById('sim-monthly-div').textContent = `折合每月资产净增值 ~$${Math.round(annualGain / years / 12).toLocaleString('en-US')}`;\n document.getElementById('sim-yoc').textContent = growthPct.toFixed(2) + '%';\n document.getElementById('sim-cum-div').textContent = initialShares.toFixed(1) + ' 股';\n document.getElementById('sim-shares-end').textContent = `起始持仓股数：${initialShares.toFixed(1)} 股 (股价 $105.8)`;\n }\n\n const KPI_STORAGE_KEY = 'ew_research_kpi_state_v1';\n\n function loadKpiChecklist() {\n try {\n const saved = localStorage.getItem(KPI_STORAGE_KEY);\n if (saved) {\n const stateMap = JSON.parse(saved);\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n if (typeof stateMap[cb.id] === 'boolean') {\n cb.checked = stateMap[cb.id];\n }\n });\n }\n } catch (e) {}\n updateKpiChecklist();\n }\n\n function updateKpiChecklist() {\n const checkboxes = document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]');\n const total = checkboxes.length;\n let checkedCount = 0;\n const stateMap = {};\n\n checkboxes.forEach(cb => {\n stateMap[cb.id] = cb.checked;\n if (cb.checked) checkedCount++;\n });\n\n const pct = Math.round((checkedCount / total) * 100);\n document.getElementById('kpi-progress-badge').textContent = `已核查 ${checkedCount} / ${total} 项 (${pct}%)`;\n\n try {\n localStorage.setItem(KPI_STORAGE_KEY, JSON.stringify(stateMap));\n } catch (e) {}\n }\n\n function resetKpiChecklist() {\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n cb.checked = false;\n });\n updateKpiChecklist();\n }\n\n let bizChartInstance = null;\n let radarChartInstance = null;\n let compMarginChartInstance = null;\n let valEvolutionChartInstance = null;\n let currentBizMode = 'revenue_mix';\n\n function getChartColors() {\n const isDark = document.documentElement.classList.contains('dark');\n return {\n text: isDark ? '#CBD5E1' : '#475569',\n grid: isDark ? 'rgba(51, 65, 85, 0.5)' : 'rgba(226, 232, 240, 0.85)',\n radarAngle: isDark ? 'rgba(71, 85, 105, 0.6)' : 'rgba(203, 213, 225, 0.85)'\n };\n }\n\n function initBizChart() {\n const ctx = document.getElementById('bizArchitectureChart').getContext('2d');\n const colors = getChartColors();\n\n const mixConfig = {\n type: 'bar',\n data: {\n labels: ['2022', '2023', '2024', '2025', '2026E'],\n datasets: [\n {\n label: 'TAVR 业务营收 ($B)',\n data: [3.7, 3.9, 4.2, 4.6, 4.9],\n backgroundColor: '#3B82F6',\n borderRadius: 4,\n stack: 'rev'\n },\n {\n label: 'TMTT 二/三尖瓣营收 ($B)',\n data: [0.1, 0.2, 0.4, 0.6, 0.79],\n backgroundColor: '#10B981',\n borderRadius: 4,\n stack: 'rev'\n },\n {\n label: '外科与重症监护营收 ($B)',\n data: [1.3, 1.4, 1.4, 1.5, 1.6],\n backgroundColor: '#06B6D4',\n borderRadius: 4,\n stack: 'rev'\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n }\n },\n scales: {\n x: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n },\n y: {\n min: 0,\n max: 8,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n }\n }\n }\n };\n\n const metricsConfig = {\n type: 'bar',\n data: {\n labels: [\n 'Q3 TMTT 销售额同比增速 (常定汇率)',\n 'Q3 TAVR 销售额同比增速 (常定汇率)',\n 'Q3 全球总销售额同比增速 (常定汇率)',\n 'Q3 调整后 EPS 同比增速',\n 'Q3 整体毛利率 Gross Margin'\n ],\n datasets: [\n {\n label: '经营指标表现 (%)',\n data: [45.6, 8.8, 11.2, 19.0, 78.5],\n backgroundColor: ['#10B981', '#3B82F6', '#2563EB', '#059669', '#06B6D4'],\n borderRadius: 6,\n barThickness: 22\n }\n ]\n },\n options: {\n indexAxis: 'y',\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: { display: false },\n tooltip: {\n callbacks: {\n label: (ctx) => `指标数值: ${ctx.parsed.x}%`\n }\n }\n },\n scales: {\n x: {\n min: 0,\n max: 90,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n },\n y: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n };\n\n if (bizChartInstance) bizChartInstance.destroy();\n bizChartInstance = new Chart(ctx, currentBizMode === 'revenue_mix' ? mixConfig : metricsConfig);\n }\n\n function switchBizChart(mode) {\n currentBizMode = mode;\n const btnRev = document.getElementById('btn-chart-rev');\n const btnMet = document.getElementById('btn-chart-met');\n const titleEl = document.getElementById('biz-chart-title');\n const subEl = document.getElementById('biz-chart-sub');\n\n if (mode === 'revenue_mix') {\n btnRev.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-medblue-600 dark:text-medblue-400 shadow-sm transition cursor-pointer';\n btnMet.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer';\n titleEl.textContent = '2022–2026E 全球净营收与 TAVR/TMTT 分板块演进';\n subEl.textContent = 'TAVR 构成绝对基本盘，TMTT（二尖瓣与三尖瓣疗法）实现爆发式高增速';\n } else {\n btnMet.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-medblue-600 dark:text-medblue-400 shadow-sm transition cursor-pointer';\n btnRev.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer';\n titleEl.textContent = '2026Q3 各业务板块增速与核心运营指标拆解';\n subEl.textContent = 'TMTT 业务大增 45.6%，毛利率坚挺在 78.5% 行业顶尖水平';\n }\n initBizChart();\n }\n\n function initRadarChart() {\n const ctx = document.getElementById('moatRadarChart').getContext('2d');\n const colors = getChartColors();\n\n if (radarChartInstance) radarChartInstance.destroy();\n radarChartInstance = new Chart(ctx, {\n type: 'radar',\n data: {\n labels: [\n 'TAVR 瓣膜技术统治力',\n '长期临床数据证据壁垒',\n '毛利率与定价权',\n '医院与医生高粘性生态',\n '现金流与资产负债表健康度'\n ],\n datasets: [\n {\n label: '爱德华生命科学 (EW)',\n data: [9.9, 9.8, 9.7, 9.6, 9.8],\n borderColor: '#3B82F6',\n backgroundColor: 'rgba(59, 130, 246, 0.24)',\n pointBackgroundColor: '#3B82F6',\n borderWidth: 2.5\n },\n {\n label: '美敦力 (MDT)',\n data: [8.5, 8.4, 8.0, 8.5, 8.8],\n borderColor: '#10B981',\n backgroundColor: 'rgba(16, 185, 129, 0.14)',\n pointBackgroundColor: '#10B981',\n borderWidth: 2.0\n },\n {\n label: '波士顿科学 (BSX)',\n data: [8.0, 8.1, 8.3, 8.2, 8.5],\n borderColor: '#06B6D4',\n backgroundColor: 'rgba(6, 182, 212, 0.12)',\n pointBackgroundColor: '#06B6D4',\n borderWidth: 1.8,\n borderDash: [4, 4]\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n }\n },\n scales: {\n r: {\n min: 0,\n max: 10,\n ticks: { display: false, stepSize: 2 },\n grid: { color: colors.grid },\n angleLines: { color: colors.radarAngle },\n pointLabels: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initCompMarginChart() {\n const ctx = document.getElementById('compMarginChart').getContext('2d');\n const colors = getChartColors();\n\n if (compMarginChartInstance) compMarginChartInstance.destroy();\n compMarginChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: [\n '爱德华生命科学 (EW · 瓣膜绝对专精)',\n '波士顿科学 (BSX · 心血管介入)',\n '美敦力 (MDT · 综合医疗器械)',\n '雅培 (ABT · 医疗诊断与心血管)'\n ],\n datasets: [\n {\n label: '毛利率 Gross Margin (%)',\n data: [78.5, 69.0, 65.0, 56.0],\n backgroundColor: '#3B82F6',\n borderRadius: 5,\n barThickness: 16\n },\n {\n label: '远期 P/E 估值倍数',\n data: [34.5, 31.0, 16.5, 22.0],\n backgroundColor: '#10B981',\n borderRadius: 5,\n barThickness: 16\n }\n ]\n },\n options: {\n indexAxis: 'y',\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n },\n tooltip: {\n callbacks: {\n label: (ctx) => `${ctx.dataset.label}: ${ctx.parsed.x}${ctx.datasetIndex === 0 ? '%' : 'x'}`\n }\n }\n },\n scales: {\n x: {\n max: 90,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '' }\n },\n y: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initValEvolutionChart() {\n const ctx = document.getElementById('valEvolutionChart').getContext('2d');\n const colors = getChartColors();\n\n if (valEvolutionChartInstance) valEvolutionChartInstance.destroy();\n valEvolutionChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: ['2021', '2022', '2023', '2024', '2025', '2026E'],\n datasets: [\n {\n type: 'bar',\n label: '净营收 Net Revenue ($B)',\n data: [5.38, 5.50, 6.01, 6.23, 6.55, 6.85],\n backgroundColor: 'rgba(59, 130, 246, 0.85)',\n borderRadius: 5,\n barThickness: 28,\n yAxisID: 'y'\n },\n {\n type: 'line',\n label: '调整后稀释 EPS ($/股)',\n data: [2.40, 2.56, 2.62, 2.75, 2.88, 3.01],\n borderColor: '#10B981',\n backgroundColor: '#10B981',\n borderWidth: 3,\n pointRadius: 5,\n pointHoverRadius: 7,\n tension: 0.25,\n yAxisID: 'y1'\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n }\n },\n scales: {\n x: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n },\n y: {\n type: 'linear',\n position: 'left',\n min: 4,\n max: 8,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v.toFixed(1) + 'B' },\n title: { display: true, text: '净营收 ($B)', color: colors.text, font: { size: 11 } }\n },\n y1: {\n type: 'linear',\n position: 'right',\n min: 1.5,\n max: 3.5,\n grid: { drawOnChartArea: false },\n ticks: { color: '#10B981', font: { size: 11, weight: '600' }, callback: v => '$' + v.toFixed(2) },\n title: { display: true, text: '调整后 EPS ($/股)', color: '#10B981', font: { size: 11 } }\n }\n }\n }\n });\n }\n\n function updateChartsTheme() {\n initBizChart();\n initRadarChart();\n initCompMarginChart();\n initValEvolutionChart();\n }\n\n window.addEventListener('DOMContentLoaded', () => {\n loadKpiChecklist();\n updateDividendSimulator();\n initBizChart();\n initRadarChart();\n initCompMarginChart();\n initValEvolutionChart();\n });\n </script>\n</body>\n</html>"};
